import static java.lang.System.out;public class NoSunshine{public static void main(String[] args){String a="Ain't no sunshine when she's gone";String b="And this house just ain't no home";String c="Anytime she goes away";C(a,"It's not warm when she's away","And she's always gone too long",c);C("Wonder this time where she's gone", "Wonder if she's gone to stay",b,c);I();out.println("Hey, I ought to leave young thing alone\nBut "+a+", woah-woah\n");C(a,"Only darkness every day",b,c);for(int i=0;i<3;i++){out.println(c);}}public static void I(){out.print("And ");for(int i=0;i<5;i++){for(int j=0;j<4;j++){out.print("I know, ");}out.println("I know");}out.println("I know, I know\n");}public static void C(String x,String y,String z,String w){out.println(x+"\n"+y+"\n"+x+"\n"+z+"\n"+w+"\n");}}